import { NextResponse } from 'next/server';
import { getSupabaseServer, requireUser } from '../../../../lib/supabase/server';
export const runtime='nodejs';
export async function POST(request){try{const u=await requireUser(request),b=await request.json(),db=getSupabaseServer();const {data:m,error:me}=await db.from('menus').select('id,vendor_id').eq('id',b.menu_id).single();if(me||!m)throw new Error('Menu not found.');const {data:v}=await db.from('vendors').select('id').eq('id',m.vendor_id).eq('owner_id',u.id).single();if(!v)throw new Error('You do not own this menu.');if(!b.name?.trim())return NextResponse.json({error:'Item name is required.'},{status:400});const {data,error}=await db.from('menu_items').insert({menu_id:m.id,name:b.name.trim(),description:b.description||null,ingredients:b.ingredients||[],allergens:b.allergens||[],dietary_attributes:b.dietary_attributes||[],nutrition_attributes:b.nutrition_attributes||[],price:Math.max(0,Number(b.price||0))}).select().single();if(error)throw error;return NextResponse.json({item:data},{status:201})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message},{status:e.message==='Unauthorized'?401:400})}}
